  "implementation": "def solve(case):
    import json
    nodes = case['nodes']
    core = case['core_distance']
    dists = case['distances']
    edges = []
    for a, b, d in dists:
        # canonicalize: store with smaller first
        if a > b:
            a, b = b, a
        w = max(core[a], core[b], d)
        edges.append((w, a, b))
    # sort by weight, then by a, then b (lexicographic)
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total = 0.0
    count = 0
    n = len(nodes)
    for w, a, b in edges:
        if union(a, b):
            mst_edges.append([a, b, w])
            total += w
            count += 1
            if count == n - 1:
                break
    # The input is assumed connected; if not, MST would be incomplete.
    # Still return whatever edges were chosen (should be n-1).
    return {'mst_edges': mst_edges, 'total_weight': total}"
}
